  align-items: center;
  gap: 14px;
  padding: 10px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background-color: var(--surface);
  box-shadow: var(--shadow);
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s;

  &:hover {
    border-color: var(--accent);
  }

  &.watched {
    background-color: var(--surface-muted);

    .title-link {
      color: var(--text-muted);
    }
  }
}

.watched-checkbox {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  margin: 0;
  accent-color: var(--success);
  cursor: pointer;
}

.thumb {
  flex-shrink: 0;
  width: 46px;
  height: 69px;
  border-radius: 6px;
  object-fit: cover;
}

.thumb-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--surface-muted);
}

// Text column grows, but the link inside only covers the title text
.item-text {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  min-width: 0;
}

.title-link {
  color: var(--text);
  font-weight: 700;
  text-decoration: none;

  &:hover {
    color: var(--accent);
    text-decoration: underline;
  }
}

.year {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.status-pill {
  flex-shrink: 0;
  padding: 2px 10px;
  border-radius: 999px;
  background-color: var(--surface-muted);
  color: var(--text-muted);
  font-size: 0.8rem;
  font-weight: 600;

  .watched & {
    background-color: var(--surface);
    color: var(--success);
  }

  @media (max-width: 480px) {
    display: none;
  }
}

.remove-btn {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: none;
  border-radius: 50%;
  background: none;
  color: var(--text-muted);
  font-size: 1rem;
